package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"

	"github.com/go-chi/chi/v5"
	"github.com/go-chi/chi/v5/middleware"
)

func main() {
	r := chi.NewRouter()
	r.Use(middleware.AllowMethods("GET", "POST"))
	r.Handle("/a", http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
		w.Write([]byte("success"))
	}))

	tests := []struct {
		method string
		path   string
	}{
		{"GET", "/a"},
		{"DELETE", "/a"},
		{"POST", "/a"},
	}

	for _, test := range tests {
		w := httptest.NewRecorder()
		req := httptest.NewRequest(test.method, test.path, http.NoBody)
		r.ServeHTTP(w, req)
		fmt.Printf("%s %s -> %d", test.method, test.path, w.Code)
		if allow := w.Header().Get("Allow"); allow != "" {
			fmt.Printf(", Allow: %s", allow)
		}
		fmt.Println()
	}
}
EOF

