package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"

	"github.com/go-chi/chi/v5"
	"github.com/go-chi/chi/v5/middleware"
)

func main() {
	r := chi.NewRouter()
	r.Use(middleware.BlockUserAgents("curl", "BadBot"))
	r.Get("/", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
		w.Write([]byte("OK"))
	})

	tests := []struct {
		name      string
		userAgent string
		expected  int
	}{
		{"curl/8.0", "curl/8.0", http.StatusForbidden},
		{"Mozilla with badbot", "Mozilla/5.0 (compatible; badbot/1.2)", http.StatusForbidden},
		{"Mozilla/5.0 allowed", "Mozilla/5.0", http.StatusOK},
		{"no user agent", "", http.StatusOK},
	}

	for _, test := range tests {
		req := httptest.NewRequest("GET", "/", http.NoBody)
		if test.userAgent != "" {
			req.Header.Set("User-Agent", test.userAgent)
		}
		w := httptest.NewRecorder()
		r.ServeHTTP(w, req)
		status := "✓"
		if w.Code != test.expected {
			status = "✗"
		}
		fmt.Printf("%s GET / with User-Agent: %q -> %d (expected %d)\n", status, test.userAgent, w.Code, test.expected)
	}
}
EOF
go run /tmp/test_block_agents.go

