	"net/http/httptest"
	"github.com/go-chi/chi/v5"
	"github.com/go-chi/chi/v5/middleware"
)

func main() {
	r := chi.NewRouter()
	r.Use(middleware.MaxHeaderCount(2))
	r.Get("/", func(w http.ResponseWriter, r *http.Request) {
		w.Write([]byte("success"))
	})

	tests := []struct {
		name        string
		headers     map[string]string
		expectCode  int
	}{
		{"no headers", map[string]string{}, 200},
		{"two headers", map[string]string{"A": "1", "B": "2"}, 200},
		{"three headers", map[string]string{"A": "1", "B": "2", "C": "3"}, 431},
	}

	for _, test := range tests {
		req := httptest.NewRequest("GET", "/", nil)
		for k, v := range test.headers {
			req.Header.Set(k, v)
		}
		w := httptest.NewRecorder()
		r.ServeHTTP(w, req)
		status := "✓"
		if w.Code != test.expectCode {
			status = "✗"
		}
		fmt.Printf("%s %s: got %d (expected %d)\n", status, test.name, w.Code, test.expectCode)
	}
}
